$r=Join-Path $PSScriptRoot "reports";$f="BrokerReviewQueue.json","MigrationPreview.json","OwnershipAudit.json","MigrationDashboard.json";$ok=0;foreach($i in $f){if(Test-Path (Join-Path $r $i)){$ok++}};$s=if($ok-eq4){"PASS"}else{"FAIL"};@{status=$s;commitEnabled=$false;outboundBlocked=$true}|ConvertTo-Json|Set-Content (Join-Path $r "MigrationReadiness.json");if($s-eq"PASS"){Write-Host "[PASS]";exit 0}else{Write-Host "[FAIL]";exit 1}